chart.options:
chart: {
  height: 350,
  type: 'bar',
},
dataLabels: {
  enabled: false
},
title: {
  text: 'Ajax Example',
},
noData: {
  text: 'Loading...'
},
xaxis: {
  type: 'category',
  tickPlacement: 'on',
  labels: {
    rotate: -45,
    rotateAlways: true
  }
}

vanilla-js-script:
// Served straight off this repository's own db.json, so the demo does not
// depend on a third-party fake-API staying alive.
axios({
  method: 'GET',
  url: 'https://cdn.jsdelivr.net/gh/apexcharts/apexcharts.js@main/db.json',
}).then(function(response) {
  chart.updateSeries([{
    name: 'Sales',
    data: response.data.yearly
  }])
})
